#include <iostream>
#include <string>
#include <unordered_map>
#include <vector>
using namespace std;

int main() {
    unordered_map<string, int> cnt;
    vector<string> order;

    string word;
    while (cin >> word) {
        if (cnt.count(word) == 0) {
            order.push_back(word);
        }
        cnt[word]++;
    }

    for (auto &w : order) {
        cout << w << " " << cnt[w] << endl;
    }
    return 0;
}

