#include <iostream>
#include <unordered_map>
using namespace std;

int main() {
    int n, target;
    cin >> n >> target;

    unordered_map<int, int> pos;   // 数字 -> 它第一次出现的位置（从 1 开始）
    bool found = false;
    int ansI = 0;
    int ansJ = 0;

    for (int i = 1; i <= n; i++) {
        int x;
        cin >> x;

        if (!found) {
            int need = target - x;
            if (pos.count(need) == 1) {
                found = true;
                ansI = pos[need];
                ansJ = i;
            }
        }

        if (pos.count(x) == 0) {
            pos[x] = i;
        }
    }

    if (found) {
        cout << ansI << " " << ansJ << endl;
    } else {
        cout << "NO" << endl;
    }
    return 0;
}

