    int n;
    cin >> n;

    map<int, int> cnt;
    for (int i = 0; i < n; i++) {
        int x;
        cin >> x;
        cnt[x]++;
    }

    int bestNum = 0;
    int bestCnt = 0;
    for (auto &kv : cnt) {
        if (kv.second > bestCnt) {
            bestCnt = kv.second;
            bestNum = kv.first;
        }
    }

    cout << bestNum << " " << bestCnt << endl;
